// seevio.mjs — adapter SeeVio (seevio.ai) para a camada PROVIDERS.
//
// O SeeVio agrega o Seedance da ByteDance com formato async de tarefa:
//   - POST /v1/videos/generations -> tarefa (id) com reserva de créditos
//   - GET  /v1/tasks/{taskId}     -> { status: completed|failed, data: {...} }
// Autenticação Bearer SEEVIO_API_KEY em tudo.
//
// Formato segue a documentação pública (seevio.ai/api-docs, lida 2026-09-13):
//   - Body de submit: `{ model, input: { prompt, generation_type, duration,
//     aspect_ratio, image_urls?, ... } }`.
//   - Poll ≥10s; a resposta de conclusão `data.results[]` carrega URLs de vídeo que EXPIREM
//     (`data.video_expires_at`): o núcleo espelha os outputs para data/outputs
//     imediatamente após o poll devolver, o que cobre o prazo. Cobrança é
//     crédito pré-pago por tarefa (`data.credits`, `billing_status`).
//   - 402/insufficient_credits é erro terminal: o adapter NÃO reenvia (reenvio
//     de submit pode cobrar duas vezes).
//   - Igual ao atlas/kie: só URL pública em imagem (data URI é descartado cedo;
//     o anexo da UI vira URL pública no storage do fal).

const BASE = "https://api.seevio.ai";
const POLL_MS = 10000;
const JOB_TIMEOUT_MS = 15 * 60 * 1000;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const LANES = {
  "text-to-video": "text-to-video",
  "image-to-video": "image-to-video",
};

const modelOf = (modelId) => {
  const stripped = modelId.replace(/^seevio\//, "");
  for (const lane of Object.keys(LANES)) {
    if (stripped.endsWith(`/${lane}`)) return { model: stripped.slice(0, -(lane.length + 1)), lane };
  }
  throw new Error(`seevio: id ${modelId} não termina em /text-to-video nem /image-to-video.`);
};

function key() {
  const k = process.env.SEEVIO_API_KEY;
  if (!k) throw new Error("SEEVIO_API_KEY ausente. Crie em seevio.ai.");
  return k;
}
const headers = () => ({ Authorization: `Bearer ${key()}`, "Content-Type": "application/json" });

function uriDeEntrada(input) {
  const brutas = [];
  for (const campo of ["image", "image_url", "image_urls", "images"]) {
    const v = input?.[campo];
    if (Array.isArray(v)) brutas.push(...v);
    else if (typeof v === "string" && v) brutas.push(v);
  }
  const publicas = brutas.filter((r) => typeof r === "string" && /^https?:\/\//.test(r));
  if (brutas.length && !publicas.length) {
    throw new Error("seevio exige imagem como URL pública (não aceita data URI nem caminho local).");
  }
  return publicas;
}

async function submit(modelId, input) {
  const { model, lane } = modelOf(modelId);
  const entrada = {
    prompt: input.prompt,
    generation_type: lane,
    duration: input.duration ?? 5,
    aspect_ratio: input.aspect_ratio ?? "16:9",
  };
  if (input.seed !== undefined && input.seed !== null && input.seed !== -1) entrada.seed = input.seed;
  if (typeof input.generate_audio === "boolean") entrada.generate_audio = input.generate_audio;
  const imagens = uriDeEntrada(input);
  if (lane === "image-to-video") {
    if (!imagens.length) throw new Error("seevio i2v precisa de um frame inicial como URL pública.");
    entrada.image_urls = imagens;
  }
  const res = await fetch(`${BASE}/v1/videos/generations`, {
    method: "POST",
    headers: headers(),
    body: JSON.stringify({ model, input: entrada }),
    signal: AbortSignal.timeout(120000),
  });
  const text = await res.text();
  if (res.status === 402) {
    throw new Error(`seevio: créditos insuficientes (402): ${text.slice(0, 200)}`);
  }
  if (!res.ok) throw new Error(`seevio generations HTTP ${res.status}: ${text.slice(0, 300)}`);
  const payload = JSON.parse(text);
  const data = payload?.data ?? payload;
  const id = data?.id ?? data?.task_id ?? data?.taskId;
  if (!id) throw new Error(`seevio generations sem id de tarefa: ${text.slice(0, 200)}`);
  return { request_id: id };
}

async function poll(modelId, handle, { onUpdate } = {}) {
  const started = Date.now();
  let esperar = POLL_MS;
  while (Date.now() - started < JOB_TIMEOUT_MS) {
    await sleep(esperar);
    esperar = POLL_MS;
    let payload;
    try {
      const r = await fetch(`${BASE}/v1/tasks/${encodeURIComponent(handle.request_id)}`, {
        headers: headers(), signal: AbortSignal.timeout(60000),
      });
      if (r.status === 429) {
        // Honrar Retry-After e seguir esperando: 429 não é terminal.
        const ra = Number(r.headers.get("retry-after"));
        if (Number.isFinite(ra) && ra > 0) esperar = Math.min(ra * 1000, 60_000);
        onUpdate?.({ status: "IN_QUEUE" });
        continue;
      }
      const text = await r.text();
      payload = JSON.parse(text);
      if (!r.ok) {
        const codigo = payload?.error?.code ?? payload?.code;
        if (codigo === "internal_error") { onUpdate?.({ status: "IN_QUEUE" }); continue; }
        if (r.status >= 500) { onUpdate?.({ status: "IN_QUEUE" }); continue; }
        throw new Error(`seevio tarefa HTTP ${r.status}: ${text.slice(0, 250)}`);
      }
    } catch (e) {
      // Falha de transporte isolada não mata a tarefa; falha REPORTADA sim.
      if (e && /HTTP 4\d\d/.test(e.message)) throw e;
      onUpdate?.({ status: "IN_QUEUE" });
      continue;
    }

    const data = payload?.data ?? payload;
    // A API devolve status e id no CORPO DE CIMA (`{"status": ..., "id": ...,
    // "data": {...}}`); o `data` carrega results/credits, SEM status. Medido na
    // primeira tarefa viva (2026-09-14): ler o status lá em cima.
    const estado = String(payload?.status ?? data?.status ?? "").toLowerCase();
    onUpdate?.({ status: estado === "completed" ? "IN_PROGRESS" : "IN_QUEUE" });

    if (estado === "completed") {
      const resultados = Array.isArray(data?.results) ? data.results : [];
      const urls = resultados
        .map((o) => (typeof o === "string" ? o : o?.url ?? o?.video_url))
        .filter((u) => typeof u === "string" && /^https?:\/\//.test(u));
      if (!urls.length) throw new Error("seevio concluiu sem devolver URL de vídeo em data.results.");
      const creditos = [payload?.credits, data?.credits].map(Number).find((n) => Number.isFinite(n)) ?? null;
      if (data?.video_expires_at) {
        const prazo = new Date(data.video_expires_at).getTime();
        if (Number.isFinite(prazo)) {
          const minutos = Math.round((prazo - Date.now()) / 60000);
          console.log(`seevio: ${urls.length} saída(s) com expiração em ${data.video_expires_at} (~${minutos} min — o núcleo espelha agora em data/outputs).`);
        }
      }
      return {
        result: { video: { url: urls[0], content_type: "video/mp4" } },
        billableUnits: creditos,
      };
    }
    if (estado === "failed") {
      throw new Error(`seevio reportou falha: ${JSON.stringify(data?.error ?? data ?? payload).slice(0, 250)}`);
    }
  }
  throw new Error("seevio: tempo esgotado (15 min).");
}

export const seevioProvider = {
  label: "SeeVio",
  availability: () => process.env.SEEVIO_API_KEY
    ? { available: true }
    : { available: false, reason: "Falta SEEVIO_API_KEY", hint: "Crie em seevio.ai. Cobra em creditos pre-pagos por tarefa." },
  // Só URL pública em imagem, como atlas/kie; o anexo da UI vira URL pública
  // no storage do fal antes de chegar aqui.
  accepts: { dataUri: false },
  submit,
  poll,
  quote: () => ({
    cost: null,
    confidence: "unknown",
    basis: "SeeVio cobra em créditos pré-pagos por tarefa e não publica preço por API; o custo só aparece depois (data.credits).",
  }),
  // O SeeVio mede em CRÉDITOS; não existe conversão anunciada crédito→dólar.
  // Sem inventar conversão (mesma regra do kie): o custo em dólar fica null e
  // os créditos medidos entram em unit/billable_units.
  actual: (modelId, billableUnits) => {
    if (billableUnits == null) {
      return {
        cost: null,
        confidence: "measured (créditos não reportados)",
        basis: "SeeVio não devolveu data.credits para esta tarefa.",
        unit: "credits",
        billable_units: null,
      };
    }
    return {
      cost: null,
      confidence: "measured (créditos medidos)",
      basis: `${billableUnits} créditos SeeVio consumidos (reportados na tarefa)`,
      unit: "credits",
      billable_units: billableUnits,
    };
  },
};

export default seevioProvider;

